#define main pairing_antecedent_main
#include "../cm8-61-pairing-20261115/pairing.cpp"
#undef main
using Poly=std::vector<F>;
void trim(Poly&a){while(!a.empty()&&a.back()==F())a.pop_back();}
int deg(const Poly&a){return int(a.size())-1;}
Poly scale(Poly a,F b){for(auto&x:a)x=x*b;trim(a);return a;}
Poly sub(Poly a,const Poly&b){a.resize(std::max(a.size(),b.size()));for(size_t i=0;i<b.size();i++)a[i]=a[i]-b[i];trim(a);return a;}
struct Unknown{};
int peak;
void bound(int n,int cap){if(n>cap)throw Unknown{};peak=std::max(peak,n);}
Poly product(const Poly&a,const Poly&b,int cap,int weight=0){if(a.empty()||b.empty())return {};bound(deg(a)+deg(b)+weight,cap);Poly c(a.size()+b.size()-1);for(size_t i=0;i<a.size();i++)for(size_t j=0;j<b.size();j++)c[i+j]=c[i+j]+a[i]*b[j];trim(c);return c;}
std::pair<Poly,Poly> divide(Poly a,const Poly&b,int cap){need(!b.empty(),"zero divisor");Poly q;if(deg(a)>=deg(b))q.resize(deg(a)-deg(b)+1);while(!a.empty()&&deg(a)>=deg(b)){int k=deg(a)-deg(b);F v=a.back()/b.back();q[k]=q[k]+v;Poly mono(k+1);mono[k]=v;a=sub(a,product(mono,b,cap));}trim(q);return{q,a};}
struct Cert{Poly f,h,d,u,v;};
Cert certify(const std::vector<F>&a,const std::vector<F>&b,F z,int cap){bound(3,cap);Poly f{F(1)},h{F(1)};for(auto x:a)f=product(f,Poly{F()-x,F(1)},cap);for(auto x:b)h=product(h,Poly{z,F()-x},cap);Poly r0=f,r1=h,u0{F(1)},u1,v0,v1{F(1)};while(!r1.empty()){auto[q,r]=divide(r0,r1,cap);Poly u=sub(u0,product(q,u1,cap,3)),v=sub(v0,product(q,v1,cap,3));r0=r1;r1=r;u0=u1;u1=u;v0=v1;v1=v;}F k=F(1)/r0.back();r0=scale(r0,k);u0=scale(u0,k);v0=scale(v0,k);need(sub(sub(product(u0,f,cap),scale(product(v0,h,cap),F()-F(1))),r0).empty(),"Bezout identity");need(divide(f,r0,cap).second.empty()&&divide(h,r0,cap).second.empty(),"gcd divisibility");return{f,h,r0,u0,v0};}
F eval(const Poly&a,F x){F z;for(size_t i=a.size();i-->0;)z=z*x+a[i];return z;}
std::string poly(const Poly&a){std::ostringstream o;o<<a.size();for(F x:a)o<<','<<encode(x);return o.str();}
int main(int argc,char**argv){try{if(argc==5&&std::string(argv[1])=="mutate"){std::ifstream in(argv[2]);need(bool(in),"input");std::vector<std::vector<std::string>>ls;std::string line;while(std::getline(in,line)){std::istringstream row(line);std::vector<std::string>v;std::string x;while(row>>x)v.push_back(x);ls.push_back(v);}auto old=ls;std::string mode=argv[4];bool done=false;if(mode=="source"){ls[0][1]="60";done=true;}else if(mode=="cap"){ls[0][5]="8";done=true;}else if(mode=="degree"){ls.back()[1]="0";done=true;}else if(mode=="missing-cap"){for(size_t i=ls.size();i-->0;)if(ls[i][0]=="CELL"&&ls[i][1]=="8"){ls.erase(ls.begin()+i);done=true;}}else for(size_t i=0;i<ls.size();i++){auto&v=ls[i];if(v[0]!="CELL")continue;if(mode=="missing-query"&&v[5]=="U"){ls.erase(ls.begin()+i);done=true;break;}if(v[5]!="C")continue;if(mode=="witness"){v[10]="1,1";done=true;break;}if(mode=="root"&&v[9]!="1,1"){v[9]="1,1";done=true;break;}if(mode=="row"&&v[12]!="0"){v[13]="9,9";done=true;break;}}need(done&&ls!=old,"no semantic mutation");std::ifstream prior(argv[3]);need(!prior.good(),"fresh output");std::ofstream out(argv[3]);for(auto&v:ls){for(size_t i=0;i<v.size();i++){if(i)out<<' ';out<<v[i];}out<<'\n';}return 0;}need(argc==1,"no arguments or mutate INPUT NEW MODE");P g{F(0),F(10),false},u{F(37),F(14),false},s=chi(u);auto src=group(g,21,39);std::vector<P> base;for(P q:src)if(!q.o&&std::pair(encode(q.x),encode(q.y))<std::pair(encode(neg(q).x),encode(neg(q).y)))base.push_back(q);base.resize(3);std::cout<<"F61GCD 61 59 31 3 9 31 4\nBASE";for(P q:base){std::cout<<' ';point(q);}std::cout<<'\n';int certified=0,unknown=0,rows=0,maxpeak=0;for(int cap=0;cap<=8;cap++)for(int qi=0;qi<31;qi++){P q=src[qi];F z=*pairing(q,s);for(int sign:{-1,1})for(int sign2:{-1,1}){std::vector<F>a,b;for(P x:base){a.push_back(*pairing(sign==1?x:neg(x),s));b.push_back(*pairing(sign2==1?x:neg(x),s));}peak=0;std::cout<<"CELL "<<cap<<' '<<qi<<' '<<sign<<' '<<sign2<<' ';try{Cert c=certify(a,b,z,cap);std::vector<std::pair<int,int>>found;for(int i=0;i<3;i++)if(eval(c.d,a[i])==F())for(int j=0;j<3;j++)if(a[i]*b[j]==z){need(add(sign==1?base[i]:neg(base[i]),sign2==1?base[j]:neg(base[j]))==q,"source row lift");found.push_back({i,j});}std::vector<std::pair<int,int>>ref;for(int i=0;i<3;i++)for(int j=0;j<3;j++)if(add(sign==1?base[i]:neg(base[i]),sign2==1?base[j]:neg(base[j]))==q)ref.push_back({i,j});need(found==ref,"complete ordered branch coverage");std::cout<<"C "<<peak<<' '<<poly(c.f)<<' '<<poly(c.h)<<' '<<poly(c.d)<<' '<<poly(c.u)<<' '<<poly(c.v)<<' '<<found.size();for(auto[i,j]:found)std::cout<<' '<<i<<','<<j;std::cout<<'\n';certified++;rows+=found.size();maxpeak=std::max(maxpeak,peak);}catch(const Unknown&){std::cout<<"U "<<peak<<'\n';unknown++;}}}std::cout<<"CHECK "<<certified<<' '<<unknown<<' '<<rows<<' '<<maxpeak<<"\nMATRIX NA\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 101;}}
